Actually in the classic implementation, the alignment applies to total nbytes. Let me write:

```c
#define SECTOR_SIZE 512

static void write_segment(Elf64_Phdr phdr, FILE * fp, FILE * img, int *nbytes)
{
    if (phdr.p_memsz == 0)
        return;

    fseek(fp, phdr.p_offset, SEEK_SET);

    /* copy the file contents of the segment */
    long remaining = phdr.p_filesz;
    char buf[SECTOR_SIZE];
    while (remaining > 0) {
        int chunk = remaining > SECTOR_SIZE ? SECTOR_SIZE : (int)remaining;
        fread(buf, chunk, 1, fp);
        fwrite(buf, chunk, 1, img);
        *nbytes += chunk;
        remaining -= chunk;
    }

    /* zero-fill the rest of the segment (bss) */
    memset(buf, 0, SECTOR_SIZE);
    remaining = phdr.p_memsz - phdr.p_filesz;
    while (remaining > 0) {
        int chunk = remaining > SECTOR_SIZE ? SECTOR_SIZE : (int)remaining;
        fwrite(buf, chunk, 1, img);
        *nbytes += chunk;
        remaining -= chunk;
    }

    /* pad the image to a 512-byte boundary */
    int padding = SECTOR_SIZE - (*nbytes % SECTOR_SIZE);
    if (padding != SECTOR_SIZE) {
        fwrite(buf, padding, 1, img);
        *nbytes += padding;
    }
}

static void write_os_size(int nbytes, FILE * img)
{
    /* record the OS size in sectors at offset 508 of the image;
       the OS starts right after the 512-byte bootblock */
    int os_sectors = nbytes / SECTOR_SIZE - 1;
    fseek(img, 508, SEEK_SET);
    fwrite(&os_sectors, sizeof(int), 1, img);
    fseek(img, nbytes, SEEK_SET); // hmm not needed
}
```

