static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
{
    list_head *bucket = &futex_buckets[futex_hash((uint64_t)val_addr)];
    list_node_t *node;
    futex_node_t *fnode;

    /* look up the node whose key is `val_addr` in the hash bucket */
    for (node = bucket->next; node != bucket; node = node->next) {
        fnode = list_entry(node, futex_node_t, list);
        if (fnode->futex_key == (futex_key_t)val_addr) {
            return fnode;
        }
    }

    if (!create) {
        return NULL;
    }

    /* allocate and initialize a new futex node */
    fnode = (futex_node_t *)kmalloc(sizeof(futex_node_t));
    assert(fnode != NULL);
    fnode->futex_key = (futex_key_t)val_addr;
    init_list_head(&fnode->block_queue);
    list_add_tail(&fnode->list, bucket);

    return fnode;
}

void futex_wait(volatile uint64_t *val_addr, uint64_t val)
{
    futex_node_t *node;

    disable_preempt();
    if (*val_addr != val) {
        /* the value has changed, do not block */
        enable_preempt();
        return;
    }

    node = get_node(val_addr, 1);
    do_block(&current_running->list, &node->block_queue);
    enable_preempt();
    do_scheduler();
}

void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
{
    futex_node_t *node;

    disable_preempt();
    node = get_node(val_addr, 0);
    if (node != NULL) {
        while (num_wakeup-- > 0 && !list_empty(&node->block_queue)) {
            do_unblock(node->block_queue.next);
        }
    }
    enable_preempt();
}

