args.new_string:
void binsem_op(int binsem_id, int op)
{
    binsem_node_t *node = &binsem_nodes[binsem_id];
    pcb_t *cur = current_running[cpu_id];

    if (op == BINSEM_OP_LOCK) {
        if (node->sem > 0) {
            /* the semaphore is available, take it */
            node->sem--;
        } else {
            /* block on the semaphore; when woken up, the semaphore
               is handed over to us by the unlock operation */
            do_block(&cur->list, &node->block_queue);
            scheduler();
        }
        /* record the acquired semaphore so that it can be
           released automatically when the process exits */
        cur->binsem_id[cur->binsem_num++] = binsem_id;
    } else if (op == BINSEM_OP_UNLOCK) {
        /* remove the semaphore from the process's acquired list */
        for (int i = 0; i < cur->binsem_num; i++) {
            if (cur->binsem_id[i] == binsem_id) {
                cur->binsem_id[i] = cur->binsem_id[--cur->binsem_num];
                break;
            }
        }
        if (!list_empty(&node->block_queue)) {
            /* hand the semaphore over to a blocked waiter */
            do_unblock(node->block_queue.next);
        } else {
            node->sem++;
        }
    }
}

