int do_mbox_send(int mailbox_id, void *msg, int msg_length)
{
    message_t *mbox = &message[mailbox_id];

    if (mbox->msg_len != 0) {
        /* the mailbox is full: block on its wait queue and re-execute
           this system call (via sepc) after being woken up; return
           mailbox_id so that the saved a0 remains valid on retry */
        regs_context_t *regs =
            (regs_context_t *)current_running[cpu_id]->kernel_sp;
        regs->sepc -= 4;
        do_block(&current_running[cpu_id]->list, &mbox->wait_queue);
        scheduler();
        return mailbox_id;
    }

    /* deposit the message */
    kmemcpy(mbox->msg, (char *)msg, msg_length);
    mbox->msg_len = msg_length;

    /* wake up a blocked receiver if any */
    if (!list_empty(&mbox->wait_queue)) {
        do_unblock(mbox->wait_queue.next);
    }

    return msg_length;
}

int do_mbox_recv(int mailbox_id, void *msg, int msg_length)
{
    message_t *mbox = &message[mailbox_id];

    if (mbox->msg_len == 0) {
        /* the mailbox is empty: block on its wait queue and re-execute
           this system call (via sepc) after being woken up; return
           mailbox_id so that the saved a0 remains valid on retry */
        regs_context_t *regs =
            (regs_context_t *)current_running[cpu_id]->kernel_sp;
        regs->sepc -= 4;
        do_block(&current_running[cpu_id]->list, &mbox->wait_queue);
        scheduler();
        return mailbox_id;
    }

    /* fetch the message */
    int length = msg_length < mbox->msg_len ? msg_length : mbox->msg_len;
    kmemcpy((char *)msg, mbox->msg, length);
    mbox->msg_len = 0;

    /* wake up a blocked sender if any */
    if (!list_empty(&mbox->wait_queue)) {
        do_unblock(mbox->wait_queue.next);
    }

    return length;
}

