/*
 * walk the three-level page table of `pgdir` (pa) for `va` and return
 * the pointer (kva) to the leaf-level PTE; intermediate tables are
 * allocated when `create` is non-zero.  Returns NULL when `create` is
 * zero and some intermediate table is missing.
 */
static PTE* walk_page_table(uintptr_t va, uintptr_t pgdir, int create)
{
    PTE *pgdir_kva = (PTE *)pa2kva(pgdir);
    int vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *l2_entry = pgdir_kva + vpn2;
    if (!get_attribute(*l2_entry, _PAGE_PRESENT)) {
        PTE *new_table;
        if (!create) {
            return NULL;
        }
        new_table = alloc_pgdir_page();
        set_pfn(l2_entry, (uintptr_t)new_table >> NORMAL_PAGE_SHIFT);
        set_attribute(l2_entry, _PAGE_PRESENT);
    }
    PTE *l1_table = (PTE *)pa2kva(get_pa(*l2_entry));

    PTE *l1_entry = l1_table + vpn1;
    if (!get_attribute(*l1_entry, _PAGE_PRESENT)) {
        PTE *new_table;
        if (!create) {
            return NULL;
        }
        new_table = alloc_pgdir_page();
        set_pfn(l1_entry, (uintptr_t)new_table >> NORMAL_PAGE_SHIFT);
        set_attribute(l1_entry, _PAGE_PRESENT);
    }
    PTE *l0_table = (PTE *)pa2kva(get_pa(*l1_entry));

    return l0_table + vpn0;
}

/* find the leaf PTE (kva) mapping physical address `pa` in `pgdir` (pa) */
static PTE* find_pte_by_pa(PTE *pgdir, uintptr_t pa)
{
    PTE *l2_table = (PTE *)pa2kva((uintptr_t)pgdir);

    for (int i = 0; i < NUM_PTE_ENTRY; i++) {
        if (i == 0x001 || i == 0x101) {
            continue;   /* skip the shared kernel large-page entries */
        }
        if (!get_attribute(l2_table[i], _PAGE_PRESENT)) {
            continue;
        }
        PTE *l1_table = (PTE *)pa2kva(get_pa(l2_table[i]));
        for (int j = 0; j < NUM_PTE_ENTRY; j++) {
            if (!get_attribute(l1_table[j], _PAGE_PRESENT)) {
                continue;
            }
            PTE *l0_table = (PTE *)pa2kva(get_pa(l1_table[j]));
            for (int k = 0; k < NUM_PTE_ENTRY; k++) {
                if (get_attribute(l0_table[k], _PAGE_PRESENT) &&
                    get_pa(l0_table[k]) == pa) {
                    return &l0_table[k];
                }
            }
        }
    }
    return NULL;
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    static int clock_hand = 0;

    /* NRU (clock) algorithm: give pages whose accessed bit is set
       a second chance by clearing the bit; the first unpinned valid
       page with a clear accessed bit is selected as the victim */
    while (1) {
        int i = clock_hand;
        clock_hand = (clock_hand + 1) % USER_PAGE_NUM;

        if (user_page[i].valid == 0 || user_page[i].pin != 0) {
            continue;
        }

        ptr_t pa = num2pa(i);
        PTE *pte = find_pte_by_pa(user_page[i].pgtable, pa);
        if (pte == NULL) {
            /* not mapped anymore, safe to reuse */
            return pa;
        }
        if (get_attribute(*pte, _PAGE_ACCESSED)) {
            clear_attribute(pte, _PAGE_ACCESSED);
        } else {
            return pa;
        }
    }
}

void write_to_sd(ptr_t pa)
{
    /* search for a free disk slot in the swap area */
    int i;
    for (i = 0; i < DISK_PAGE_NUM; i++) {
        if (disk_page[i].valid == 0) {
            break;
        }
    }
    assert(i != DISK_PAGE_NUM);
    disk_page[i].valid = 1;

    /* write the page content to the swap area on the SD card */
    sbi_sd_write(pa, SECTORS_PER_PAGE, SWAP_BEGIN + i * SECTORS_PER_PAGE);

    /* mark the corresponding PTE as swapped out: the disk slot id is
       recorded in the PFN field and the software bit is set */
    PTE *pte = find_pte_by_pa(user_page[pa2num(pa)].pgtable, pa);
    assert(pte != NULL);
    set_pfn(pte, i);
    clear_attribute(pte, _PAGE_PRESENT);
    set_attribute(pte, _PAGE_SOFT);
    flush_tlb_all();

    /* the physical page is free now */
    user_page[pa2num(pa)].valid = 0;
}

