PTE* init_page_table()
{
    /* allocate a fresh page directory (returns pa, already cleared) */
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir_kva = (PTE *)pa2kva(PGDIR_PA);

    /* copy the kernel large-page mappings so that the kernel remains
       reachable (traps, kernel stacks, pa2kva) while this process runs;
       both entries share the kernel's second-level table */
    pgdir_kva[0x001] = kernel_pgdir_kva[0x001];
    pgdir_kva[0x101] = kernel_pgdir_kva[0x101];

    return pgdir;
}

void free_process_user_page(PTE* pgdir)
{
    PTE *l2_table = (PTE *)pa2kva((uintptr_t)pgdir);

    for (int i = 0; i < NUM_PTE_ENTRY; i++) {
        if (i == 0x001 || i == 0x101) {
            continue;   /* keep the shared kernel mappings */
        }
        if (!get_attribute(l2_table[i], _PAGE_PRESENT)) {
            continue;
        }
        PTE *l1_table = (PTE *)pa2kva(get_pa(l2_table[i]));
        for (int j = 0; j < NUM_PTE_ENTRY; j++) {
            if (!get_attribute(l1_table[j], _PAGE_PRESENT)) {
                continue;
            }
            PTE *l0_table = (PTE *)pa2kva(get_pa(l1_table[j]));
            for (int k = 0; k < NUM_PTE_ENTRY; k++) {
                PTE pte = l0_table[k];
                if (get_attribute(pte, _PAGE_SOFT)) {
                    /* swapped-out page: release the disk slot */
                    disk_page[get_pfn(pte)].valid = 0;
                    continue;
                }
                if (!get_attribute(pte, _PAGE_PRESENT)) {
                    continue;
                }
                uintptr_t pa = get_pa(pte);
                uintptr_t va = ((uintptr_t)i << VPN2_SHIFT) |
                               ((uintptr_t)j << VPN1_SHIFT) |
                               ((uintptr_t)k << VPN0_SHIFT);
                if (va >= SHM_BASE && va < SHM_END) {
                    /* shared memory page: only release the physical page
                       when no process maps it anymore */
                    for (int s = 0; s < SHM_PAGE_NUM; s++) {
                        if (shm_page[s].count > 0 && shm_page[s].pa == pa) {
                            if (--shm_page[s].count == 0) {
                                free_user_page(pa);
                            }
                            break;
                        }
                    }
                } else {
                    free_user_page(pa);
                }
            }
            free_pgdir_page(get_pa(l1_table[j]));
        }
        free_pgdir_page(get_pa(l2_table[i]));
    }

    free_pgdir_page((uintptr_t)pgdir);
}

uintptr_t shm_page_get(int key)
{
    int slot = key % SHM_PAGE_NUM;
    pcb_t *cur = current_running[cpu_id];

    /* allocate the shared physical page on first use */
    if (shm_page[slot].count == 0) {
        uintptr_t pa = alloc_user_page(1, NULL);    /* pinned: never swapped */
        memset((void *)pa2kva(pa), 0, PAGE_SIZE);
        shm_page[slot].pa = pa;
    }

    /* find a free virtual address in the shared memory region */
    uintptr_t va;
    for (va = SHM_BASE; va < SHM_END; va += PAGE_SIZE) {
        PTE *pte = walk_page_table(va, (uintptr_t)cur->pgdir, 0);
        if (pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)) {
            break;
        }
    }
    if (va >= SHM_END) {
        return 0;
    }

    /* map the shared page into the current process */
    PTE *pte = walk_page_table(va, (uintptr_t)cur->pgdir, 1);
    set_pfn(pte, shm_page[slot].pa >> NORMAL_PAGE_SHIFT);
    set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                  _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
    shm_page[slot].count++;
    flush_tlb_all();

    return va;
}

void shm_page_dt(uintptr_t addr)
{
    pcb_t *cur = current_running[cpu_id];
    uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE);

    PTE *pte = walk_page_table(va, (uintptr_t)cur->pgdir, 0);
    if (pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)) {
        return;
    }

    uintptr_t pa = get_pa(*pte);

    /* unmap the page from the current process */
    *pte = 0;
    flush_tlb_all();

    /* decrease the reference count of the shared page */
    for (int s = 0; s < SHM_PAGE_NUM; s++) {
        if (shm_page[s].count > 0 && shm_page[s].pa == pa) {
            if (--shm_page[s].count == 0) {
                free_user_page(pa);
            }
            break;
        }
    }
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    pcb_t *cur = current_running[cpu_id];
    uintptr_t va = ROUNDDOWN(stval, PAGE_SIZE);

    PTE *pte = walk_page_table(va, (uintptr_t)cur->pgdir, 1);
    assert(pte != NULL);

    if (get_attribute(*pte, _PAGE_SOFT)) {
        /* the page was swapped out to disk: swap it back in */
        int disk_id = get_pfn(*pte);
        ptr_t pa = alloc_user_page(0, cur->pgdir);
        sbi_sd_read(pa, SECTORS_PER_PAGE, SWAP_BEGIN + disk_id * SECTORS_PER_PAGE);
        disk_page[disk_id].valid = 0;

        set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
        clear_attribute(pte, _PAGE_SOFT);
        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                      _PAGE_EXEC | _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
    } else {
        /* demand paging: allocate a fresh zeroed anonymous page */
        ptr_t pa = alloc_user_page(0, cur->pgdir);
        memset((void *)pa2kva(pa), 0, PAGE_SIZE);

        set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                      _PAGE_EXEC | _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
    }

    flush_tlb_all();
}

